const char CORE_WEB_HTML[] = R"COREWEB(<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="theme-color" content="#0d1117">
<title>ECLIPSE CORE WEB</title>
<style>:root{color-scheme:dark;--bg:#0d1117;--panel:#161b22;--line:#30363d;--text:#e6edf3;--muted:#8b949e;--blue:#58a6ff;--cyan:#79c0ff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 50% -20%,#17304d 0,transparent 48%),var(--bg);color:var(--text);font:15px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif;min-height:100vh}.topbar{height:76px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 max(22px,calc((100% - 1040px)/2));background:#0d1117e8}.brand{display:flex;align-items:center;gap:12px}.mark{display:grid;place-items:center;width:38px;height:38px;border:1px solid #28639b;border-radius:11px;color:var(--blue);font-weight:800;font-size:22px}.brand strong,.brand small{display:block;letter-spacing:.12em}.brand small{color:var(--muted);font-size:10px}.status{display:flex;align-items:center;gap:9px;color:var(--muted);font-size:11px;letter-spacing:.1em}.status i{width:8px;height:8px;border-radius:50%;background:#8b949e}.status.online{color:#3fb950}.status.online i{background:#3fb950;box-shadow:0 0 12px #3fb95088}main{max-width:1040px;margin:auto;padding:46px 22px}.hero{margin-bottom:30px}.eyebrow{color:var(--blue);font-size:11px;letter-spacing:.2em;font-weight:700}.hero h1{font-size:clamp(34px,7vw,58px);line-height:1.05;letter-spacing:-.055em;margin:8px 0}.hero h1 span{color:var(--blue)}.muted{color:var(--muted)}.small{font-size:13px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.panel{background:linear-gradient(145deg,#1b222c,#131920);border:1px solid var(--line);border-radius:16px;padding:22px;box-shadow:0 12px 40px #0002}.device{min-height:245px}.sensors{grid-column:1/-1}.panel-head{display:flex;justify-content:space-between;color:#a5b4c3;font-size:11px;font-weight:700;letter-spacing:.14em;margin-bottom:20px}.live{color:#3fb950}.big{font-size:28px;font-weight:750;letter-spacing:-.04em;margin:12px 0 20px}.meta,.sensor-row{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-top:1px solid #252d37;font-size:12px}.meta span,.sensor-row span{color:var(--muted)}.meta strong,.sensor-row strong{font-weight:600;color:var(--text)}.dpad{display:flex;flex-direction:column;align-items:center;gap:8px;margin:20px 0 12px}.dpad>div{display:flex;gap:8px}.dpad button, .back{min-width:54px;min-height:46px}.dpad button,.back{border:1px solid #34465b;border-radius:10px;background:#1d2a39;color:var(--text);font-weight:700;cursor:pointer}.dpad button.primary{padding:0 20px;background:#153c60;border-color:#28639b;color:#d8ecff}.dpad button:disabled{opacity:.2}.back{width:100%;min-height:40px;background:#171d26;color:#a5b4c3}.dpad button:active,.back:active{transform:scale(.97);border-color:var(--blue)}button:focus-visible{outline:2px solid var(--blue);outline-offset:3px}.hint{color:var(--muted);font-size:11px;margin:13px 0 0;min-height:17px}footer{display:flex;justify-content:space-between;color:#66717e;font-size:10px;letter-spacing:.12em;margin-top:32px}@media(max-width:680px){main{padding-top:32px}.grid{grid-template-columns:1fr}.sensors{grid-column:auto}.panel{padding:19px}.topbar{padding:0 18px}footer{gap:12px;flex-direction:column}}</style>
</head>
<body>
<header class="topbar"><div class="brand"><span class="mark">E</span><div><strong>ECLIPSE CORE</strong><small>WEB CONTROL</small></div></div><div id="connection" class="status"><i></i><span>CONNECTING</span></div></header>
<main>
<section class="hero"><p class="eyebrow">LOCAL DEVICE INTERFACE</p><h1>CORE <span>CONTROL</span></h1><p class="muted">Your device. Your network. No cloud required.</p></section>
<section class="grid">
<article class="panel device"><div class="panel-head"><span>DEVICE STATUS</span><span class="live">LIVE</span></div><div id="deviceState" class="big">SEARCHING</div><div class="meta"><span>IP ADDRESS</span><strong id="ipAddress">—</strong></div><div class="meta"><span>APPLICATION</span><strong id="appState">—</strong></div><div class="meta"><span>UPTIME</span><strong id="uptime">—</strong></div></article>
<article class="panel"><div class="panel-head">REMOTE NAVIGATION</div><p class="muted small">These controls act like the physical rotary encoder and back button.</p><div class="dpad"><button data-action="up" aria-label="Move up">▲</button><div><button data-action="left" disabled aria-label="Move left">←</button><button data-action="select" class="primary">SELECT</button><button data-action="right" disabled aria-label="Move right">→</button></div><button data-action="down" aria-label="Move down">▼</button></div><button data-action="back" class="back">BACK</button><p id="commandMessage" class="hint">Connect to the same Wi-Fi network as CORE.</p></article>
<article class="panel sensors"><div class="panel-head">SENSOR SNAPSHOT</div><div class="sensor-row"><span>LIGHT</span><strong id="light">—</strong></div><div class="sensor-row"><span>DISTANCE</span><strong id="distance">—</strong></div><div class="sensor-row"><span>TEMPERATURE</span><strong id="temperature">—</strong></div><div class="sensor-row"><span>HUMIDITY</span><strong id="humidity">—</strong></div><p class="hint">Readings update when the corresponding CORE sensor app refreshes them.</p></article>
</section>
<footer> ECLIPSE CORE WEB <span>LOCAL NETWORK ONLY · V1</span></footer>
</main>
<script>const $=id=>document.getElementById(id);let online=false;async function refresh(){try{const r=await fetch('/api/v1/status',{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json();online=!!d.wifiConnected;$('connection').classList.toggle('online',online);$('connection').querySelector('span').textContent=online?'CONNECTED':'OFFLINE';$('deviceState').textContent=online?'CORE ONLINE':'CORE OFFLINE';$('ipAddress').textContent=d.ip||'—';$('appState').textContent=d.app||'—';$('uptime').textContent=d.uptimeSeconds!=null?formatTime(d.uptimeSeconds):'—';$('light').textContent=d.light!=null?d.light+' / 1023':'—';$('distance').textContent=d.distanceCm!=null?d.distanceCm+' cm':'—';$('temperature').textContent=d.temperatureF!=null?d.temperatureF+' °F':'—';$('humidity').textContent=d.humidity!=null?d.humidity+'%':'—';}catch(e){online=false;$('connection').classList.remove('online');$('connection').querySelector('span').textContent='NOT CONNECTED';$('deviceState').textContent='WAITING FOR CORE';}}function formatTime(s){const h=Math.floor(s/3600),m=Math.floor(s%3600/60),sec=s%60;return h+'h '+m+'m '+sec+'s'}async function send(action){if(!online){$('commandMessage').textContent='CORE is not connected. Check that your phone and Arduino are on the same Wi-Fi.';return}try{const r=await fetch('/api/v1/input/'+action,{method:'POST'});if(!r.ok)throw Error('Command rejected');$('commandMessage').textContent='Command sent: '+action.toUpperCase();}catch(e){$('commandMessage').textContent='Could not send command.'}}document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>send(b.dataset.action)));refresh();setInterval(refresh,1500);</script>
</body></html>)COREWEB";
